  `is_active` int NOT NULL DEFAULT 1 COMMENT '1=启用 0=禁用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_type_store` (`template_type`,`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批模板表';

