--
-- Table structure for table `staff_master`
--

DROP TABLE IF EXISTS `staff_master`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `staff_master` (
  `staff_id` int NOT NULL AUTO_INCREMENT,
  `store_id` bigint NOT NULL DEFAULT '1',
  `staff_name` varchar(20) NOT NULL,
  `staff_account` varchar(20) DEFAULT NULL,
  `staff_password` varchar(100) DEFAULT NULL,
  `staff_gender` varchar(2) DEFAULT NULL,
  `staff_age` int DEFAULT NULL,
  `staff_phone` varchar(20) DEFAULT NULL,
  `staff_position` varchar(50) DEFAULT NULL,
  `department` varchar(50) DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  `monthly_salary` decimal(10,2) DEFAULT '0.00',
  `id_card` varchar(20) DEFAULT NULL,
  `home_address` varchar(100) DEFAULT NULL,
  `emergency_contact` varchar(20) DEFAULT NULL,
  `emergency_phone` varchar(20) DEFAULT NULL,
  `employment_status` varchar(10) DEFAULT 'active',
  `resign_reason` text,
  `resign_date` date DEFAULT NULL,
  `role` varchar(30) DEFAULT NULL,
  `remark` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `permission_level` int DEFAULT '0',
  `dept_id` int DEFAULT NULL,
  `can_manage_kitchen` tinyint DEFAULT '0',
  `can_manage_sales` tinyint DEFAULT '0',
  `can_manage_finance` tinyint DEFAULT '0',
  `can_manage_hr` tinyint DEFAULT '0',
  `can_view_all_stores` tinyint DEFAULT '0',
  `can_edit_system` tinyint DEFAULT '0',
  `staff_no` varchar(20) DEFAULT NULL,
  `avatar_url` varchar(500) DEFAULT NULL,
  `nation` varchar(20) DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `native_place` varchar(100) DEFAULT NULL,
  `marital_status` varchar(10) DEFAULT NULL,
  `political_status` varchar(20) DEFAULT NULL,
  `education` varchar(20) DEFAULT NULL,
  `major` varchar(50) DEFAULT NULL,
  `graduate_school` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `wechat` varchar(50) DEFAULT NULL,
  `staff_rank` varchar(20) DEFAULT NULL,
  `employment_type` varchar(20) DEFAULT NULL,
  `hire_channel` varchar(30) DEFAULT NULL,
  `probation_months` decimal(3,1) DEFAULT NULL,
  `probation_start_date` date DEFAULT NULL,
  `probation_end_date` date DEFAULT NULL,
  `regular_date` date DEFAULT NULL,
  `leader_id` int DEFAULT NULL,
  `work_location` varchar(100) DEFAULT NULL,
  `basic_salary` decimal(12,2) DEFAULT NULL,
  `performance_salary` decimal(12,2) DEFAULT NULL,
  `subsidy` decimal(12,2) DEFAULT NULL,
  `bonus` decimal(12,2) DEFAULT NULL,
  `social_insurance` decimal(12,2) DEFAULT NULL,
  `housing_fund` decimal(12,2) DEFAULT NULL,
  `bank_name` varchar(50) DEFAULT NULL,
  `bank_account` varchar(30) DEFAULT NULL,
  `account_holder` varchar(20) DEFAULT NULL,
  `entry_age` int DEFAULT NULL,
  `work_years` decimal(5,2) DEFAULT NULL,
  PRIMARY KEY (`staff_id`),
  KEY `idx_store` (`store_id`),
  KEY `idx_account` (`staff_account`),
  KEY `idx_phone` (`staff_phone`),
  KEY `idx_status` (`employment_status`),
  KEY `fk_staff_dept` (`dept_id`),
  CONSTRAINT `fk_staff_dept` FOREIGN KEY (`dept_id`) REFERENCES `department` (`dept_id`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

