-- ============================================================
-- Stage1-Task3: DBTrae Database Emergency Repair Optimization
-- 1. Redundant table data migration and cleanup
-- 2. Global time field naming unification (created_at->create_time, updated_at->update_time)
-- 3. Unique indexes on key fields
-- 4. Foreign key constraints with ON DELETE RESTRICT
-- ============================================================

SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;

-- Safe conditional FK drop helper (reused in PART 2 and PART 5)
DROP PROCEDURE IF EXISTS p_drop_fk_safe;
DELIMITER //
CREATE PROCEDURE p_drop_fk_safe(IN p_table VARCHAR(64), IN p_fk VARCHAR(64))
BEGIN
    DECLARE v_count INT DEFAULT 0;
    SELECT COUNT(*) INTO v_count
      FROM information_schema.TABLE_CONSTRAINTS
     WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = p_table AND CONSTRAINT_NAME = p_fk AND CONSTRAINT_TYPE = 'FOREIGN KEY';
    IF v_count > 0 THEN
        SET @sql = CONCAT('ALTER TABLE `', p_table, '` DROP FOREIGN KEY `', p_fk, '`');
        PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
    END IF;
END //
DELIMITER ;

-- ------------------------------------------------------------
-- PART 1: Redundant table data migration
-- ------------------------------------------------------------

-- 1.1 Fix attendance_records.staff_id all-NULL issue (SET staff_id = emp_id)
UPDATE attendance_records SET staff_id = emp_id WHERE staff_id IS NULL;

-- 1.2 dishes -> dish_master data migration
INSERT INTO dish_master (dish_id, store_id, dish_name, english_name, sale_price, price, unit, sort_order)
SELECT id, 1, name, en, price, price, unit, sort_order
FROM dishes
ON DUPLICATE KEY UPDATE
    dish_name = VALUES(dish_name),
    english_name = VALUES(english_name),
    sale_price = VALUES(sale_price),
    price = VALUES(price),
    unit = VALUES(unit),
    sort_order = VALUES(sort_order);

-- 1.3 packages -> package_master data migration
INSERT INTO package_master (package_id, store_id, package_name, package_total_price, price, description)
SELECT code, 1, name, price, price, `desc`
FROM packages
ON DUPLICATE KEY UPDATE
    package_name = VALUES(package_name),
    package_total_price = VALUES(package_total_price),
    price = VALUES(price),
    description = VALUES(description);

-- 1.4 meal_package -> package_master data migration
INSERT INTO package_master (package_id, store_id, package_name, package_total_price, description)
SELECT package_code, 1, package_name, COALESCE(package_price, 0), description
FROM meal_package
ON DUPLICATE KEY UPDATE
    package_name = VALUES(package_name),
    package_total_price = VALUES(package_total_price),
    description = VALUES(description);

-- 1.5 categories -> dish_category data migration
INSERT INTO dish_category (category_name, category_code, sort_order, is_active)
SELECT name, id, sort_order, 1
FROM categories
ON DUPLICATE KEY UPDATE
    category_name = VALUES(category_name),
    sort_order = VALUES(sort_order);

-- ------------------------------------------------------------
-- PART 2: Drop redundant tables
-- ------------------------------------------------------------
-- 2.1 Drop dangling FK on package_dish_rel referencing meal_package (about to be dropped)
CALL p_drop_fk_safe('package_dish_rel', 'package_dish_rel_ibfk_1');
-- 2.2 Drop redundant tables (data already migrated to target tables in PART 1)
DROP TABLE IF EXISTS dishes;
DROP TABLE IF EXISTS packages;
DROP TABLE IF EXISTS meal_package;
DROP TABLE IF EXISTS categories;

-- ------------------------------------------------------------
-- PART 3: Global time field naming unification
-- created_at -> create_time, updated_at -> update_time
-- ------------------------------------------------------------

ALTER TABLE `admin_users` CHANGE COLUMN `created_at` `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE `ai_chat_history` CHANGE COLUMN `created_at` `create_time` datetime DEFAULT CURRENT_TIMESTAMP;
