-- ------------------------------------------------------------
-- PART 4: Unique indexes on key fields
-- ------------------------------------------------------------

-- 4.1 staff_master.staff_account unique index
ALTER TABLE staff_master ADD UNIQUE KEY uk_staff_account (staff_account);

-- 4.2 booking_master.booking_no unique index
ALTER TABLE booking_master ADD UNIQUE KEY uk_booking_no (booking_no);

-- 4.3 ingredient_master.ingredient_code unique index
-- Add ingredient_code column, populate from ingredient_id (globally unique)
ALTER TABLE ingredient_master ADD COLUMN ingredient_code varchar(50) DEFAULT NULL COMMENT 'ingredient code' AFTER ingredient_id;
UPDATE ingredient_master SET ingredient_code = ingredient_id WHERE ingredient_code IS NULL;
ALTER TABLE ingredient_master ADD UNIQUE KEY uk_ingredient_code (ingredient_code);

-- 4.4 supplier_master.supplier_code unique index
-- Deduplicate supplier_code first (keep min supplier_id, set others to NULL)
UPDATE supplier_master sm1
INNER JOIN (
    SELECT supplier_code, MIN(supplier_id) AS min_id
    FROM supplier_master
    WHERE supplier_code IS NOT NULL
    GROUP BY supplier_code
    HAVING COUNT(*) > 1
) dup ON sm1.supplier_code = dup.supplier_code AND sm1.supplier_id > dup.min_id
SET sm1.supplier_code = NULL;
ALTER TABLE supplier_master ADD UNIQUE KEY uk_supplier_code (supplier_code);

-- ------------------------------------------------------------
-- PART 5: Foreign key constraints with ON DELETE RESTRICT
-- ------------------------------------------------------------

-- 5.1 booking_master(1) -> booking_table(N): booking_table.booking_master_id -> booking_master.id
-- Note: booking_table already has fk_booking_master from CREATE TABLE (without ON DELETE RESTRICT).
-- Drop and re-add with ON DELETE RESTRICT.
CALL p_drop_fk_safe('booking_table', 'fk_booking_master');
ALTER TABLE booking_table ADD CONSTRAINT fk_booking_master FOREIGN KEY (booking_master_id) REFERENCES booking_master (id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.2 booking_master(1) -> booking_dish_detail(N): booking_dish_detail.booking_id -> booking_master.booking_id
ALTER TABLE booking_dish_detail ADD CONSTRAINT fk_bdd_booking FOREIGN KEY (booking_id) REFERENCES booking_master (booking_id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.3 staff_master(1) -> attendance_records(N): attendance_records.staff_id -> staff_master.staff_id
-- Change attendance_records.staff_id from varchar(50) to int to match staff_master.staff_id
ALTER TABLE attendance_records MODIFY COLUMN staff_id int DEFAULT NULL;
ALTER TABLE attendance_records ADD CONSTRAINT fk_ar_staff FOREIGN KEY (staff_id) REFERENCES staff_master (staff_id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.4 staff_master(1) -> leave_record(N): leave_record.staff_id -> staff_master.staff_id
ALTER TABLE leave_record ADD CONSTRAINT fk_lr_staff FOREIGN KEY (staff_id) REFERENCES staff_master (staff_id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.5 staff_master(1) -> overtime(N): overtime.staff_id -> staff_master.staff_id
ALTER TABLE overtime ADD CONSTRAINT fk_ot_staff FOREIGN KEY (staff_id) REFERENCES staff_master (staff_id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.6 dish_master(1) -> dish_recipe(N): dish_recipe(dish_id,store_id) -> dish_master(dish_id,store_id)
-- dish_master has composite PK (dish_id, store_id), using composite FK
ALTER TABLE dish_recipe ADD CONSTRAINT fk_dr_dish FOREIGN KEY (dish_id, store_id) REFERENCES dish_master (dish_id, store_id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.7 ingredient_master(1) -> ingredient_inventory_log(N): (ingredient_id,store_id) -> (ingredient_id,store_id)
ALTER TABLE ingredient_inventory_log ADD CONSTRAINT fk_iil_ingredient FOREIGN KEY (ingredient_id, store_id) REFERENCES ingredient_master (ingredient_id, store_id) ON DELETE RESTRICT ON UPDATE CASCADE;

-- 5.8 ingredient_master(1) -> ingredient_purchase(N): (ingredient_id,store_id) -> (ingredient_id,store_id)
ALTER TABLE ingredient_purchase ADD CONSTRAINT fk_ip_ingredient FOREIGN KEY (ingredient_id, store_id) REFERENCES ingredient_master (ingredient_id, store_id) ON DELETE RESTRICT ON UPDATE CASCADE;

