-- 设备报修工单表
DROP TABLE IF EXISTS `maintenance_request`;
CREATE TABLE IF NOT EXISTS `maintenance_request` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `store_id` bigint NOT NULL DEFAULT '1' COMMENT '门店ID',
  `request_no` varchar(32) NOT NULL COMMENT '工单编号',
  `asset_name` varchar(100) NOT NULL COMMENT '设备/资产名称',
  `location` varchar(100) DEFAULT NULL COMMENT '故障位置',
  `priority` varchar(20) NOT NULL DEFAULT 'medium' COMMENT '优先级 high/medium/low',
  `description` text COMMENT '故障描述',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态 pending/dispatched/processing/done',
  `handler_id` int DEFAULT NULL COMMENT '处理人ID',
  `handler_name` varchar(50) DEFAULT NULL COMMENT '处理人姓名',
  `dispatch_note` varchar(500) DEFAULT NULL COMMENT '派单备注',
  `complete_note` varchar(500) DEFAULT NULL COMMENT '完工备注',
  `reporter_id` int DEFAULT NULL COMMENT '报修人ID',
  `reporter_name` varchar(50) DEFAULT NULL COMMENT '报修人姓名',
  `dispatched_at` datetime DEFAULT NULL COMMENT '派单时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_no` (`request_no`),
  KEY `idx_store_status` (`store_id`,`status`),
  KEY `idx_handler` (`handler_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='设备报修工单表';

-- 资产登记表
DROP TABLE IF EXISTS `maintenance_asset`;
CREATE TABLE IF NOT EXISTS `maintenance_asset` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `store_id` bigint NOT NULL DEFAULT '1' COMMENT '门店ID',
  `asset_no` varchar(32) NOT NULL COMMENT '资产编号',
  `asset_name` varchar(100) NOT NULL COMMENT '资产名称',
  `category` varchar(50) DEFAULT '其他' COMMENT '资产分类',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '数量',
  `unit_price` decimal(12,2) DEFAULT '0.00' COMMENT '单价',
  `department` varchar(50) DEFAULT NULL COMMENT '使用部门',
  `location` varchar(100) DEFAULT NULL COMMENT '存放位置',
  `purchase_date` date DEFAULT NULL COMMENT '购入日期',
  `status` varchar(20) NOT NULL DEFAULT '在用' COMMENT '状态 在用/维修中/报废/库存',
  `last_check_time` datetime DEFAULT NULL COMMENT '最近盘点时间',
  `last_check_user` varchar(50) DEFAULT NULL COMMENT '盘点人',
  `last_check_note` varchar(500) DEFAULT NULL COMMENT '盘点备注',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_asset_no_store` (`asset_no`,`store_id`),
  KEY `idx_store_status` (`store_id`,`status`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='资产登记表';

-- 能耗记录表
DROP TABLE IF EXISTS `energy_record`;
CREATE TABLE IF NOT EXISTS `energy_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `store_id` bigint NOT NULL DEFAULT '1' COMMENT '门店ID',
  `record_date` date NOT NULL COMMENT '记录日期',
  `energy_type` varchar(20) NOT NULL COMMENT '能耗类型 electric/water/gas',
  `meter_reading` decimal(12,2) DEFAULT NULL COMMENT '表读数',
  `consumption` decimal(12,2) DEFAULT NULL COMMENT '本次用量',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位',
  `unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价',
  `cost` decimal(12,2) DEFAULT NULL COMMENT '费用',
  `recorder_id` int DEFAULT NULL COMMENT '录入人ID',
  `recorder_name` varchar(50) DEFAULT NULL COMMENT '录入人',
  `note` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_store_date_type` (`store_id`,`record_date`,`energy_type`),
  KEY `idx_store_date` (`store_id`,`record_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='能耗记录表';

-- ============================================================
-- Stage3-Task1: 通用审批引擎 (Approval Flow Engine)
-- Tables: approval_flow, approval_node, approval_template
-- Business: leave/overtime/purchase/expense/stock_loss
-- ============================================================

-- 审批流主表
CREATE TABLE IF NOT EXISTS `approval_flow` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `flow_no` varchar(64) NOT NULL COMMENT '审批流编号',
  `flow_type` varchar(20) NOT NULL COMMENT '类型: leave/overtime/purchase/expense/stock_loss',
  `business_id` bigint NOT NULL COMMENT '业务单据ID',
  `business_no` varchar(64) DEFAULT NULL COMMENT '业务单据编号',
  `applicant_id` int DEFAULT NULL COMMENT '申请人ID',
  `applicant_name` varchar(50) DEFAULT NULL COMMENT '申请人姓名',
  `store_id` bigint NOT NULL DEFAULT '1' COMMENT '门店ID',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态: pending/approved/rejected/cancelled',
  `current_node` int NOT NULL DEFAULT '1' COMMENT '当前节点序号',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_approval_flow_no` (`flow_no`),
  KEY `idx_flow_type` (`flow_type`),
  KEY `idx_flow_business` (`flow_type`,`business_id`),
  KEY `idx_flow_status` (`status`),
  KEY `idx_flow_store` (`store_id`),
  KEY `idx_flow_applicant` (`applicant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='审批流主表';

-- 审批节点表
CREATE TABLE IF NOT EXISTS `approval_node` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `flow_id` bigint NOT NULL COMMENT '审批流ID',
  `node_order` int NOT NULL COMMENT '节点序号',
  `node_name` varchar(50) DEFAULT NULL COMMENT '节点名称',
  `approver_id` int DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(50) DEFAULT NULL COMMENT '审批人姓名',
  `status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '状态: pending/approved/rejected',
  `comment` varchar(500) DEFAULT NULL COMMENT '审批意见',
  `approved_time` datetime DEFAULT NULL COMMENT '审批时间',
  PRIMARY KEY (`id`),
  KEY `idx_node_flow` (`flow_id`),
  KEY `idx_node_approver` (`approver_id`),
  KEY `idx_node_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='审批节点表';

-- 审批模板表
CREATE TABLE IF NOT EXISTS `approval_template` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `template_type` varchar(20) NOT NULL COMMENT '类型: leave/overtime/purchase/expense/stock_loss',
  `store_id` bigint NOT NULL DEFAULT '0' COMMENT '门店ID, 0=全局通用',
  `node_count` int NOT NULL DEFAULT '1' COMMENT '节点数',
  `node1_approver_role` varchar(50) DEFAULT NULL COMMENT '节点1审批角色',
  `node2_approver_role` varchar(50) DEFAULT NULL COMMENT '节点2审批角色',
  `node3_approver_role` varchar(50) DEFAULT NULL COMMENT '节点3审批角色',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_type_store` (`template_type`,`store_id`),
  KEY `idx_template_type` (`template_type`),
  KEY `idx_template_store` (`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='审批模板表';

-- 默认审批模板种子数据: 分店单据(请假/加班/报损)->店长; 全局单据(采购/财务)->总经理
INSERT INTO `approval_template`
  (`template_type`, `store_id`, `node_count`, `node1_approver_role`, `node2_approver_role`, `node3_approver_role`, `is_active`)
VALUES
